  'trophy.board.league': 'Yönetim kurulu {manager}’ı kutluyor: {club} şampiyon!',
  'trophy.board.league.body': 'Başkan: “{club} için tarihi bir gün. {manager} bize hayalini kurduğumuz şampiyonluğu getirdi. Yönetim kurulu tam desteğini veriyor ve gelecek sezonu şimdiden heyecanla bekliyoruz.”',
  'trophy.board.leagueAgain': 'Yönetim kurulu: {manager} yine başardı – {n}. şampiyonluk!',
  'trophy.board.leagueAgain.body': 'Başkan: “Bir kez kazanmak büyük başarı. Tekrar tekrar kazanmak bir devir demek. Teşekkürler {manager} – {club} kulübünü bir hanedana dönüştürdün.”',
  'trophy.board.cup': 'Yönetim kurulu {comp} zaferin için seni kutluyor!',
  'trophy.board.cup.body': 'Başkan: “Kupaya bir yenisi eklendi – böyle geceler için çalışıyoruz. {manager}’ı ve tüm kadroyu kutluyorum.”',
  'trophy.board.cupAgain': 'Yönetim kurulu: {manager} yönetiminde {comp} yine kazanıldı – {n}. şampiyonluk!',
  'trophy.board.cupAgain.body': 'Başkan: “Bu artık güzel bir alışkanlığa dönüşüyor. Tebrikler {manager}.”',
  'trophy.board.europe': 'Avrupa zaferi! Yönetim kurulu {comp} şampiyonluğuyla coştu',
  'trophy.board.europe.body': 'Başkan: “{club}, {comp} kupasını kazandı. Kulübün yakın tarihindeki en büyük gece. {manager}, adın kulüp tarihine sonsuza dek yazıldı.”',
  'trophy.board.europeAgain': 'Yönetim kurulu: {comp} yine kazanıldı – {manager} bir efsane!',
  'trophy.board.europeAgain.body': 'Başkan: “{comp} kupasında {n}. şampiyonluk. Söyleyecek söz bulamıyorum. Teşekkürler.”',
  'trophy.fans.league': 'Şehir ayakta – binlerce taraftar şampiyonluğu kutluyor',
  'trophy.fans.league.body': 'Sokaklar {club} formaları, bayraklar ve havai fişeklerle dolu. Taraftar forumunda tek bir tezahürat var: “{manager}, {manager}, {manager}!”',
  'trophy.fans.cup': 'Taraftarlar {comp} zaferini bütün gece kutluyor',
  'trophy.fans.cup.body': 'Tribünler son düdükten çok sonra da şarkı söyledi; kupayı taşıyan otobüs stadyum dışında coşkulu taraftarlarla karşılandı.',
  'trophy.fans.europe': 'Tüm ülke {club} takımının Avrupa zaferini kutluyor',
  'trophy.fans.europe.body': 'On binlerce taraftar takımı havaalanında karşıladı. Her yerde “Bunu asla unutmayacağız” diyorlar.',
  'trophy.captain.league': '{player}: “Bu şampiyonluk senin ve taraftarlarımız için patron”',
  'trophy.captain.league.body': 'Kaptan: “İlk günden beri bize inandın. Soyunma odasındaki herkes senin için duvarları aşar. Teşekkürler patron.”',
  'trophy.captain.cup': '{player}: “Final öncesinde bize inanç verdin”',
  'trophy.captain.cup.body': 'Kaptan: “Maç öncesi konuşman tam yerindeydi. Bu kupayı senin için kazanmak istedik.”',
  'trophy.captain.europe': '{player}: “Hayatımın en güzel gecesi – teşekkürler patron”',
  'trophy.captain.europe.body': 'Kaptan: “Çocukken bu kupayı kaldırmanın hayalini kurardım. Bunu mümkün kıldın.”',
