  'land.supportLine': 'Oyun ücretsizdir ve toplulukla birlikte geliştirilir.',
  'land.community': 'Önerileri gör ve oy ver →', 'land.promoPill': 'Yeni oyun modu',
  'land.promoTitle': 'Draft Ligi: arkadaşlarınla hayalindeki takımı kur',
  'land.promoText': 'Oyundaki en iyi 500 oyuncudan kurgusal bir kulüp kur. Her seçim için 60 saniyen var; sesli sohbet de açık. Ardından tek bir akşamda birbirinize karşı tam bir sezon oynayın.',
  'land.promoCta': 'Draft Ligi hakkında bilgi al', 'land.docTitle': 'TACTICA FC – efsanevi futbol menajerliği, tarayıcında ücretsiz',
  'land.nav.features': 'Özellikler', 'land.nav.screens': 'Ekran görüntüleri', 'land.nav.ranking': 'Sıralama', 'land.nav.faq': 'Sık sorulanlar',
  'land.play': 'Ücretsiz oyna', 'land.playShort': 'Hemen oyna', 'land.seeScreens': 'Oyunu gör',
  'land.pill': 'Yeni sezon · 20.000’den fazla gerçek oyuncu', 'land.h1a': 'Efsane geri döndü.', 'land.h1b': 'Şimdi tarayıcında.',
  'land.lead': 'Klasik futbol menajerliği yeniden doğdu: hayalindeki takımı kur, gizli yetenekleri keşfet, basının karşısına çık ve kulübünü zirveye taşı. Üstelik maç motoru düşünüyor, yapay zekâ menajerleri de karşılık veriyor.',
  'land.check.free': 'Ücretsiz', 'land.check.nodl': 'İndirme gerektirmez', 'land.check.lang': 'Türkçe, İngilizce ve Danca', 'land.check.save': 'Otomatik kaydeder',
