  'land.stat.players': 'gerçek oyuncu', 'land.stat.clubs': 'kulüp', 'land.stat.leagues': 'lig', 'land.stat.moments': 'maç başına simüle edilen aksiyon',
  'land.featuresTitle': 'Sevdiğin her şey ve hep özlediğin her şey',
  'land.featuresSub': '2001’in klasik derinliği; modern bir motor, özenli tasarım ve her ekranda oynama imkânıyla.',
  'land.f.engine.title': 'Düşünen bir maç motoru', 'land.f.engine.text': 'Maç başına 240 aksiyon, xG, ivme ve ısı haritaları. Taktikler gerçekten önemli; açık veren hazır dizilişler yok.',
  'land.f.players.title': '20.000’den fazla gerçek oyuncu',
  'land.f.players.text': 'Dünya çapında 38 lig ve 662 kulüp: Danimarka Süper Ligi’nden Premier Lig’e ve Şampiyonlar Ligi’ne kadar.',
  'land.f.scouting.title': 'Belirsizlik içeren gözlem', 'land.f.scouting.text': 'Gözlemcilerin kesin değerleri değil, aralıkları görür. İyi gözlemciler geleceğin yıldızlarını herkesten önce bulur.',
  'land.f.press.title': 'Basın toplantıları ve oyuncu konuşmaları',
  'land.f.press.text': 'Gazetecileri yanıtla, soyunma odasında oyuncuları öv veya sertçe uyar; kendi sözlerinle.',
  'land.f.transfers.title': 'Canlı bir transfer pazarı',
  'land.f.transfers.text': 'Teklif yarışları, yükseltilen teklifler, satın alma opsiyonlu kiralamalar ve ısrarcı menajerler.',
  'land.f.ai.title': 'Kendi iradesi olan yapay zekâ rakipleri',
  'land.f.ai.text': 'Taktiklerini inceleyip maç sırasında karşılık veren menajerler. Talepleri, gruplaşmaları ve ruh hâlleri olan oyuncular.',
  'land.f.ranking.title': 'Dünya çapında menajer sıralaması',
  'land.f.ranking.text': 'Her sezon gösterdiğin başarıya göre puan kazandırır. Küçük bir kulüple beklentileri aş ve büyük kulüplerin menajerlerini geride bırak.',
  'land.f.online.title': 'Arkadaşlarınla çevrimiçi oyna',
  'land.f.online.text': 'Aynı dünyada kendi kulüplerini yönet, birbirinizin oyuncularına teklif ver ve ligde karşılaş.',
  'land.f.mobile.title': 'Her yerde, çevrimdışıyken bile',
  'land.f.mobile.text': 'Bilgisayarda, tablette veya telefonda oyna. Uygulama olarak yükle ve kaldığın yerden sürdür.',
  'land.screensTitle': 'Kendin gör', 'land.screensSub': 'Oyundan gerçek ekran görüntüleri. Büyütmek için tıkla.',
  'land.s.matchday.kicker': 'Maç günü', 'land.s.matchday.title': 'Her fırsatı takip et',
  'land.s.matchday.text': 'Maçı anlatım ve istatistiklerle canlı izle; neden kazandığını veya kaybettiğini açıkça gör.',
  'land.s.matchday.b1': 'xG, şut haritaları, ivme ve ısı haritaları',
  'land.s.matchday.b2': 'Her maçtan sonra asistanının analizi',
  'land.s.matchday.b3': 'Duraklat, taktiği değiştir ve klavyeyle oyuncu değiştir',
  'land.s.tactics.kicker': 'Taktikler', 'land.s.tactics.title': 'Planın, takımın',
  'land.s.tactics.text': 'Oyuncuları sahada sürükle, talimatları ince ayarla ve takım uyumunu geliştir.',
  'land.s.tactics.b1': '12 diziliş ve kapsamlı takım talimatları',
  'land.s.tactics.b2': 'Takım uyumu: uyruk, liderler ve birlikte geçirilen zaman',
  'land.s.tactics.b3': 'Rakipler dizilişine uyum sağlar',
  'land.s.people.kicker': 'İnsanlar', 'land.s.people.title': 'Karakter sahibi oyuncular',
  'land.s.people.text': 'Hırslı yıldızlar, sorun çıkaranlar ve liderler. Onlarla ve basınla konuş; sonuçlarına da katlan.',
  'land.s.people.b1': 'Gelişim grafikleri içeren ayrıntılı profiller',
  'land.s.people.b2': 'Bire bir konuşmalar, para cezaları ve takım toplantıları',
  'land.s.people.b3': 'Maç öncesi ve sonrası basın toplantıları',
  'land.s.career.kicker': 'Kariyer', 'land.s.career.title': 'Kendi hikâyeni yaz',
  'land.s.career.text': 'Yükselme ve düşme, kupa finalleri, Avrupa maçları ve ödül törenleri. Görevden alın, yeni işlere başvur, efsane ol.',
  'land.s.career.b1': 'Play-off ve lig aşamalarıyla gerçek lig yapıları',
  'land.s.career.b2': 'Tepki veren taraftarlar, yönetim kurulu ve mali durum',
  'land.s.career.b3': 'Genç yetenekler ve futbolu bırakan oyuncular',
  'land.rankKicker': 'Rekabet', 'land.rankTitle': 'En iyi menajer sen misin?',
  'land.rankText': 'Menajer puanı yalnızca bütçeyi değil, yaptığın işi ödüllendirir: beklentilere göre sonuçlarını, ligin gücünü, kupaları, Avrupa’yı, mali durumu ve genç oyuncuları hesaba katar. Her sezon yalnızca ilk denemen sayılır.',
  'land.rankCta': 'Kariyerine başla', 'land.rankBoard': 'Sıralama tablosu – toplam kariyer puanı',
  'land.rankEmpty': 'Sıralama tablosu henüz yeni. İlk sezonunu tamamla ve zirveye yerleş.',
  'land.stepsTitle': 'Santra vuruşundan şampiyonluğa üç adımda',
  'land.step1.title': 'Kulübünü seç', 'land.step1.text': 'Bir devi yönet veya alt ligden küçük bir kulüple zorlu mücadeleye giriş.',
  'land.step2.title': 'Takımını kur', 'land.step2.text': 'Gözlem yap, pazarlık et, antrenman yaptır ve kadronun gücünü ortaya çıkaracak taktiği bul.',
  'land.step3.title': 'Sıralamada yüksel', 'land.step3.text': 'Her sezon puan kazandırır. Sıralamadaki yerini paylaş ve arkadaşlarına meydan oku.',
  'land.faqTitle': 'Sık sorulan sorular', 'land.q1': 'Ücretli mi?',
  'land.a1': 'Hayır. Oyun ücretsizdir; reklam veya oyun içi satın alma yoktur.',
  'land.q2': 'Bir şey yüklemem gerekiyor mu?',
  'land.a2': 'Hayır, tarayıcında çalışır. Telefonuna veya bilgisayarına uygulama olarak yükleyebilir ve çevrimdışıyken de oynayabilirsin.',
  'land.q3': 'Oyunum nereye kaydediliyor?',
  'land.a3': 'Cihazına otomatik kaydedilir. Sekmeyi kapatıp daha sonra devam edebilirsin. Kayıtları dışa ve içe de aktarabilirsin.',
  'land.q4': 'Oyuncular gerçek mi?',
  'land.a4': 'Evet. Açık bir veri kümesinden (transfermarkt-datasets, CC0) 20.000’den fazla gerçek oyuncu bulunur. Yetenek değerleri piyasa değeri ve yaştan türetilir.',
  'land.q5': 'Arkadaşlarımla oynayabilir miyim?',
  'land.a5': 'Evet. Çevrimiçi oyun oluştur, kodu paylaş ve aynı dünyada kendi kulüplerinizi yönetin.',
  'land.q6': 'Bu, orijinal Championship Manager mı?',
  'land.a6': 'Hayır. Klasik menajerlik oyunlarından ilham alan, sıfırdan geliştirilmiş bağımsız bir taraftar projesidir ve kendine özgü pek çok fikri vardır.',
  'land.finalTitle': 'Kulübün seni bekliyor.', 'land.finalText': 'Düğmeye bastığında sezon başlar.',
  'land.footerData': 'Oyuncu verileri: transfermarkt-datasets (CC0)',
  'land.disclaimer': 'Bağımsız taraftar projesidir. Sports Interactive, Square Enix/Eidos veya Championship Manager markasıyla bağlantısı ya da onayı yoktur. Kulüp ve oyuncu adları ilgili sahiplerine aittir.',

